const DB='dal-consultor-videos';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let urls=[];
export function disposeMedia(){urls.forEach(URL.revokeObjectURL);urls=[];}
function database(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB,1);request.onupgradeneeded=()=>request.result.createObjectStore('videos',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
export async function mediaStore(action,value){const db=await database();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('videos',action==='list'?'readonly':'readwrite');const store=tx.objectStore('videos');const request=action==='list'?store.getAll():action==='delete'?store.delete(value):store.put(value);let result;request.onsuccess=()=>{result=request.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Armazenamento interrompido'));});}finally{db.close();}}
export async function validateVideo(file){if(!file||!file.size||file.size>1024*1024*1024)throw Error('Escolha um vídeo de até 1 GB.');if(!/^video\//.test(file.type))throw Error('Escolha um arquivo de vídeo.');const url=URL.createObjectURL(file);try{return await new Promise((resolve,reject)=>{const video=document.createElement('video');const timer=setTimeout(()=>{video.removeAttribute('src');video.load();reject(Error('Não foi possível ler este vídeo. Tente MP4 com H.264.'));},12000);video.preload='metadata';video.onloadedmetadata=()=>{clearTimeout(timer);if(!Number.isFinite(video.duration)||!video.videoWidth)reject(Error('Vídeo inválido.'));else resolve({duration:video.duration,width:video.videoWidth,height:video.videoHeight});video.removeAttribute('src');video.load();};video.onerror=()=>{clearTimeout(timer);reject(Error('Formato incompatível. Use MP4 com H.264.'));};video.src=url;});}finally{URL.revokeObjectURL(url);}}
export async function renderMedia(node,catalog,notify){disposeMedia();node.innerHTML='<p role="status">Abrindo seus vídeos…</p>';let records;try{records=await mediaStore('list');}catch{node.innerHTML='<div class="empty"><h3>O armazenamento de vídeos está indisponível</h3><p>Abra no navegador normal e confira o espaço disponível no aparelho.</p></div>';return;}if(!node.isConnected||!location.hash.startsWith('#videos'))return;let selected='',search='';const products=catalog.products.filter(p=>p.type!=='Kits');node.innerHTML=`<section class="media-intro"><div><span class="eyebrow">APLICAÇÃO E RESULTADOS</span><h3>Mostre o cuidado acontecendo.</h3><p>Vídeos salvos neste aparelho podem ser reproduzidos sem internet. Vincule cada demonstração ao produto correto.</p></div><span class="offline-pill">${records.length} vídeos salvos · ${(records.reduce((n,r)=>n+r.size,0)/1048576).toFixed(1)} MB</span></section><div class="media-filters"><label>Pesquisar<input id="video-search" type="search" placeholder="Produto, linha ou título"></label><label>Linha<select id="video-line"><option value="">Todas as linhas</option>${catalog.lines.map(l=>`<option>${escape(l.name)}</option>`).join('')}</select></label></div><div id="video-library" class="video-grid"></div><details class="media-import"><summary>Adicionar vídeo ao aparelho</summary><form id="video-import"><p>Selecione um vídeo que você possui ou recebeu da marca para apresentar. O arquivo fica somente neste navegador.</p><label>Título<input name="title" required maxlength="100" placeholder="Ex.: aplicação e acabamento com Spray 24K"></label><label>Produto<select name="product" required><option value="">Selecione o produto</option>${products.map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')}</select></label><label>Conteúdo<select name="kind"><option>Aplicação</option><option>Resultado</option><option>Antes e depois</option><option>Orientação técnica</option></select></label><label>Origem / profissional<input name="author" required maxlength="150" placeholder="Quem gravou ou forneceu o vídeo"></label><label>Arquivo de vídeo<input name="file" type="file" accept="video/*" required></label><p class="muted">MP4 com H.264 oferece maior compatibilidade. Máximo de 1 GB por arquivo. O navegador pode liberar dados se o aparelho ficar sem espaço; mantenha o original.</p><button class="button dark" type="submit">Salvar vídeo offline</button><p id="video-save-status" role="status"></p></form></details><section class="media-sources"><h3>Demonstração localizada na marca</h3><p>A página oficial do Spray 24K apresenta aplicação, ativação com calor e acabamento. Esses vídeos ainda não estão salvos no aplicativo.</p><a class="button light" href="https://dalcotone.com/products/24k-premium-spray-antifrizz" target="_blank" rel="noopener noreferrer">Ver na página oficial · requer internet ↗</a><small>Vídeos de resultados são exemplos de aplicação, sem garantia de resultado idêntico em outros cabelos.</small></section>`;
const draw=()=>{disposeMedia();const matching=records.filter(r=>(!selected||r.line===selected)&&[r.title,r.productName,r.line,r.author].join(' ').toLocaleLowerCase('pt-BR').includes(search));node.querySelector('#video-library').innerHTML=matching.length?matching.map(r=>{const url=URL.createObjectURL(r.blob);urls.push(url);return `<article class="video-card"><video controls playsinline preload="metadata" src="${url}" aria-label="${escape(r.title)}"></video><div><span class="eyebrow">${escape(r.line)} · ${escape(r.kind)}</span><h3>${escape(r.title)}</h3><p>${escape(r.productName)}</p><small>Adicionado por você · origem: ${escape(r.author)} · ${(r.size/1048576).toFixed(1)} MB · disponível offline</small><button class="button light small" data-remove-video="${r.id}">Remover do aparelho</button></div></article>`;}).join(''):'<div class="empty"><h3>Nenhum vídeo salvo'+(selected||search?' para este filtro':' no aparelho')+'</h3><p>Adicione arquivos de aplicação e resultados para apresentar sem conexão. Links de redes sociais não funcionam offline.</p></div>';};draw();node.querySelector('#video-search').oninput=e=>{search=e.target.value.toLocaleLowerCase('pt-BR');draw();};node.querySelector('#video-line').onchange=e=>{selected=e.target.value;draw();};node.querySelector('#video-library').onclick=async e=>{const button=e.target.closest('[data-remove-video]');if(!button)return;try{await mediaStore('delete',button.dataset.removeVideo);await renderMedia(node,catalog,notify);notify('Vídeo removido deste aparelho.');}catch{notify('Não foi possível remover o vídeo.');}};node.querySelector('#video-import').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button'),status=node.querySelector('#video-save-status');button.disabled=true;try{const file=form.elements.file.files[0],metadata=await validateVideo(file),p=products.find(p=>p.id===form.elements.product.value);if(!p)throw Error('Selecione um produto válido.');status.textContent='Salvando o arquivo no aparelho…';await mediaStore('put',{id:crypto.randomUUID(),title:form.elements.title.value.trim(),productId:p.id,productName:p.name,line:p.line,kind:form.elements.kind.value,author:form.elements.author.value.trim(),size:file.size,type:file.type,blob:file,savedAt:new Date().toISOString(),...metadata});await navigator.storage?.persist?.();await renderMedia(node,catalog,notify);notify('Vídeo salvo para reprodução offline.');}catch(error){status.textContent=error.name==='QuotaExceededError'?'Espaço insuficiente no aparelho. Libere espaço e tente novamente.':error.message;}finally{button.disabled=false;}};
}
